import { useState, useEffect, useRef } from "react";

const PHOTO = "data:image/jpeg;base64,";

const rnd = (a,b) => Math.random()*(b-a)+a;

const STARS = Array.from({length:120},(_,i)=>({id:i,left:rnd(0,100),top:rnd(0,100),size:Math.random()<0.2?3:2,dur:rnd(2,5),delay:rnd(0,6)}));
const HEARTS = Array.from({length:18},(_,i)=>({id:i,left:rnd(0,100),size:rnd(0.8,2),dur:rnd(6,14),delay:rnd(0,12),e:['❤️','💕','💖','🩷','💗','💓'][i%6]}));

const FLOWERS = [
  {id:0,emoji:'🌸',top:'-2%',left:'-3%',size:5.5,rot:-25,z:4,float:'floatA'},
  {id:1,emoji:'🌺',top:'-4%',right:'-2%',size:5,rot:20,z:3,float:'floatB'},
  {id:2,emoji:'🌹',top:'18%',left:'-7%',size:4.5,rot:-40,z:5,float:'floatC'},
  {id:3,emoji:'🌷',top:'15%',right:'-6%',size:4.2,rot:35,z:5,float:'floatA'},
  {id:4,emoji:'🌸',top:'42%',left:'-8%',size:3.8,rot:-15,z:3,float:'floatB'},
  {id:5,emoji:'🪷',top:'40%',right:'-7%',size:4,rot:50,z:4,float:'floatC'},
  {id:6,emoji:'🌺',top:'65%',left:'-5%',size:4.5,rot:-30,z:5,float:'floatA'},
  {id:7,emoji:'🌹',top:'63%',right:'-4%',size:4.8,rot:25,z:4,float:'floatB'},
  {id:8,emoji:'🌷',top:'82%',left:'-2%',size:3.5,rot:-50,z:3,float:'floatC'},
  {id:9,emoji:'🌸',top:'80%',right:'-3%',size:3.8,rot:40,z:3,float:'floatA'},
  {id:10,emoji:'🪷',top:'96%',left:'15%',size:4.2,rot:-20,z:4,float:'floatB'},
  {id:11,emoji:'🌺',top:'95%',right:'12%',size:4,rot:30,z:4,float:'floatC'},
  {id:12,emoji:'🌸',top:'5%',left:'20%',size:2.5,rot:10,z:2,float:'floatA'},
  {id:13,emoji:'🌹',top:'8%',right:'18%',size:2.8,rot:-12,z:2,float:'floatB'},
  {id:14,emoji:'🌷',top:'30%',left:'3%',size:2.2,rot:60,z:2,float:'floatC'},
  {id:15,emoji:'🌸',top:'55%',right:'2%',size:2.5,rot:-45,z:2,float:'floatA'},
];

export default function LoveLetter() {
  const stageRef = useRef(null);
  const [tilt, setTilt] = useState({x:0,y:0,on:false});

  useEffect(() => {
    const mv = (e) => {
      const cx=window.innerWidth/2, cy=window.innerHeight/2;
      const px=e.touches?e.touches[0].clientX:e.clientX;
      const py=e.touches?e.touches[0].clientY:e.clientY;
      setTilt({x:((px-cx)/cx)*10, y:-((py-cy)/cy)*7, on:true});
    };
    const ml = () => setTilt({x:0,y:0,on:false});
    window.addEventListener('mousemove',mv);
    window.addEventListener('touchmove',mv,{passive:true});
    window.addEventListener('mouseleave',ml);
    return ()=>{ window.removeEventListener('mousemove',mv); window.removeEventListener('touchmove',mv); window.removeEventListener('mouseleave',ml); };
  },[]);

  return (
    <div style={{background:'#060009',minHeight:'100vh',overflowX:'hidden',position:'relative',fontFamily:"Georgia, serif"}}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@1,400;1,700&family=Dancing+Script:wght@500;700&family=Cormorant+Garamond:ital,wght@1,300;1,400&display=swap');
        @keyframes twinkle{0%,100%{opacity:.15;transform:scale(1)}50%{opacity:1;transform:scale(1.8)}}
        @keyframes floatUp{0%{transform:translateY(0) scale(1);opacity:0}10%{opacity:.8}90%{opacity:.3}100%{transform:translateY(-105vh) scale(.4);opacity:0}}
        @keyframes floatA{0%,100%{transform:translateY(0px) rotate(var(--r)) scale(1)}33%{transform:translateY(-18px) rotate(calc(var(--r) + 6deg)) scale(1.06)}66%{transform:translateY(-8px) rotate(calc(var(--r) - 4deg)) scale(.97)}}
        @keyframes floatB{0%,100%{transform:translateY(-6px) rotate(var(--r)) scale(1)}40%{transform:translateY(10px) rotate(calc(var(--r) - 8deg)) scale(1.08)}70%{transform:translateY(-14px) rotate(calc(var(--r) + 3deg)) scale(.95)}}
        @keyframes floatC{0%,100%{transform:translateY(-12px) rotate(var(--r)) scale(.96)}50%{transform:translateY(8px) rotate(calc(var(--r) + 10deg)) scale(1.1)}}
        @keyframes photo3d{0%{transform:rotateY(-6deg) rotateX(3deg) translateY(0)}25%{transform:rotateY(5deg) rotateX(-4deg) translateY(-10px)}50%{transform:rotateY(7deg) rotateX(3deg) translateY(-5px)}75%{transform:rotateY(-4deg) rotateX(-2deg) translateY(-12px)}100%{transform:rotateY(-6deg) rotateX(3deg) translateY(0)}}
        @keyframes shimmer{to{background-position:300% center}}
        @keyframes fadeUp{from{opacity:0;transform:translateY(30px)}to{opacity:1;transform:translateY(0)}}
        @keyframes heartbeat{0%,100%{transform:scale(1)}14%{transform:scale(1.04)}28%{transform:scale(1)}42%{transform:scale(1.02)}}
        @keyframes glowPulse{0%,100%{text-shadow:0 0 10px rgba(255,100,120,.4),0 0 30px rgba(255,100,120,.2)}50%{text-shadow:0 0 20px rgba(255,100,120,.8),0 0 50px rgba(255,100,120,.4),0 0 80px rgba(255,100,120,.2)}}
        @keyframes signIn{from{opacity:0;transform:rotate(-3deg) scale(.7) translateX(20px)}to{opacity:1;transform:rotate(-2deg) scale(1) translateX(0)}}
        @keyframes petFall{0%{transform:translateY(-40px) rotate(0deg);opacity:0}8%{opacity:.9}92%{opacity:.5}100%{transform:translateY(105vh) rotate(600deg);opacity:0}}
      `}</style>

      {/* Stars */}
      <div style={{position:'fixed',inset:0,pointerEvents:'none',zIndex:0}}>
        {STARS.map(s=>(
          <div key={s.id} style={{position:'absolute',borderRadius:'50%',background:'white',
            width:s.size,height:s.size,left:`${s.left}%`,top:`${s.top}%`,
            animation:`twinkle ${s.dur}s ease-in-out infinite ${s.delay}s`}}/>
        ))}
      </div>

      {/* Floating hearts bg */}
      <div style={{position:'fixed',inset:0,pointerEvents:'none',zIndex:1}}>
        {HEARTS.map(h=>(
          <div key={h.id} style={{position:'absolute',bottom:-40,left:`${h.left}%`,
            fontSize:`${h.size}rem`,opacity:0,
            animation:`floatUp ${h.dur}s linear infinite ${h.delay}s`}}>{h.e}</div>
        ))}
      </div>

      {/* Content */}
      <div style={{position:'relative',zIndex:2,display:'flex',flexDirection:'column',alignItems:'center',padding:'60px 24px 100px'}}>

        {/* Heading */}
        <div style={{textAlign:'center',marginBottom:52,animation:'fadeUp 1s ease both'}}>
          <div style={{fontFamily:"'Dancing Script',cursive",color:'#d4af37',fontSize:'1rem',letterSpacing:4,marginBottom:6,opacity:.8}}>✦ for you, always ✦</div>
          <h1 style={{fontFamily:"'Dancing Script',cursive",fontSize:'clamp(3rem,9vw,5.5rem)',margin:0,lineHeight:1.05,
            background:'linear-gradient(135deg,#ffe0e6,#ff8fa3,#d4af37,#ff8fa3,#ffe0e6)',
            backgroundSize:'300% auto',WebkitBackgroundClip:'text',WebkitTextFillColor:'transparent',
            animation:'shimmer 4s linear infinite'}}>
            For V
          </h1>
        </div>

        {/* ── 3D Photo with flowers ── */}
        <div style={{position:'relative',width:'100%',maxWidth:440,marginBottom:64,perspective:1000}}>

          {/* Flower decorations */}
          {FLOWERS.map(f=>(
            <div key={f.id} style={{
              position:'absolute',...(f.right?{right:f.right}:{left:f.left}),top:f.top,
              fontSize:`${f.size}rem`,zIndex:f.z,pointerEvents:'none',
              '--r':`${f.rot}deg`,
              filter:`drop-shadow(0 4px 12px rgba(255,100,120,0.4)) drop-shadow(0 0 20px rgba(255,150,150,0.3))`,
              animation:`${f.float} ${rnd(3.5,6)}s ease-in-out infinite ${rnd(0,3)}s`,
              transformOrigin:'center center',
            }}>{f.emoji}</div>
          ))}

          {/* Photo 3D stage */}
          <div style={{
            transformStyle:'preserve-3d',
            animation: tilt.on?'none':'photo3d 7s ease-in-out infinite',
            transform: tilt.on?`rotateY(${tilt.x}deg) rotateX(${tilt.y}deg)`:undefined,
            transition: tilt.on?'transform .15s ease':'none',
            position:'relative',zIndex:3,
            margin:'0 60px',
          }}>
            <div style={{
              borderRadius:24,overflow:'hidden',position:'relative',
              boxShadow:'0 40px 80px rgba(0,0,0,.8), 0 0 0 2px rgba(255,150,170,.25), 0 0 60px rgba(255,80,100,.2), 16px 24px 40px rgba(0,0,0,.6)',
            }}>
              <img src={PHOTO} alt="us" style={{width:'100%',display:'block',filter:'saturate(1.15) contrast(1.05) brightness(1.02)'}}/>
              {/* glossy sheen */}
              <div style={{position:'absolute',inset:0,background:'linear-gradient(135deg,rgba(255,255,255,.15) 0%,rgba(255,255,255,.03) 45%,rgba(0,0,0,.12) 100%)',pointerEvents:'none'}}/>
              {/* pink tint vignette */}
              <div style={{position:'absolute',inset:0,background:'radial-gradient(ellipse at center,transparent 50%,rgba(100,0,30,.35) 100%)',pointerEvents:'none'}}/>
            </div>
            {/* ground glow */}
            <div style={{position:'absolute',bottom:-20,left:'5%',right:'5%',height:30,
              background:'radial-gradient(ellipse,rgba(200,50,80,.45) 0%,transparent 70%)',
              filter:'blur(14px)'}}/>
          </div>

          <div style={{textAlign:'center',marginTop:20,zIndex:3,position:'relative',
            fontFamily:"'Dancing Script',cursive",color:'rgba(255,180,190,.65)',
            fontSize:'1rem',letterSpacing:2}}>
            you &amp; me 🌹
          </div>
        </div>

        {/* ── Letter — no borders, floating ── */}
        <div style={{
          width:'100%',maxWidth:680,
          animation:'fadeUp 1.2s ease both .3s',
          position:'relative',
        }}>

          {/* Extra big flowers flanking the letter */}
          <div style={{position:'absolute',top:-40,left:-50,fontSize:'6rem',zIndex:0,pointerEvents:'none',opacity:.85,
            filter:'drop-shadow(0 0 25px rgba(255,100,130,.6))',
            animation:'floatA 4s ease-in-out infinite','--r':'-20deg',transformOrigin:'center'}}>🌸</div>
          <div style={{position:'absolute',top:-35,right:-45,fontSize:'5.5rem',zIndex:0,pointerEvents:'none',opacity:.85,
            filter:'drop-shadow(0 0 25px rgba(255,100,130,.6))',
            animation:'floatB 5s ease-in-out infinite .5s','--r':'25deg',transformOrigin:'center'}}>🌺</div>
          <div style={{position:'absolute',bottom:-30,left:-40,fontSize:'5rem',zIndex:0,pointerEvents:'none',opacity:.8,
            filter:'drop-shadow(0 0 20px rgba(255,100,130,.5))',
            animation:'floatC 4.5s ease-in-out infinite 1s','--r':'-35deg',transformOrigin:'center'}}>🌷</div>
          <div style={{position:'absolute',bottom:-25,right:-35,fontSize:'5rem',zIndex:0,pointerEvents:'none',opacity:.8,
            filter:'drop-shadow(0 0 20px rgba(255,100,130,.5))',
            animation:'floatA 5.5s ease-in-out infinite .3s','--r':'30deg',transformOrigin:'center'}}>🪷</div>

          {/* The actual letter — no card, no border, just floating text */}
          <div style={{position:'relative',zIndex:1,padding:'0 8px'}}>

            {/* Salutation */}
            <div style={{
              fontFamily:"'Dancing Script',cursive",
              fontSize:'clamp(1.6rem,5vw,2.4rem)',
              color:'#ff8fa3',
              marginBottom:28,
              animation:'heartbeat 2.5s ease-in-out infinite, glowPulse 3s ease-in-out infinite',
              textShadow:'0 0 20px rgba(255,100,140,.5)',
            }}>
              Hey V, 💌
            </div>

            {/* Paragraphs */}
            {[
              <>I don't even know where to start with this, but I figured I'd just write it out because some things are too big to keep just in my head. You've gotten under my skin in the best way possible, V. Like, I'll be going about my day minding my business and somehow you pop into my thoughts and I'm smiling at nothing. People probably think I'm weird. Honestly I don't even care.</>,
              <>I am <span style={{color:'#d4af37',fontWeight:600}}>so genuinely into you</span> it's kind of crazy. Not in a dramatic movie way, just in that quiet real way where I notice everything about you and I actually want to know more. The way you talk, the way you think, the way you carry yourself. You just do something to me that I really can't put into words, so I'm trying my best here.</>,
              <>And look, I know we have our moments. We argue, we get on each other's nerves sometimes, and yeah it gets heated. But every single time, when the dust settles, my first thought is still you. <span style={{fontStyle:'italic',color:'#ff8fa3',fontWeight:600}}>That tells me everything I need to know.</span> Fighting with you has never once made me want to leave. If anything it just shows me how much I actually care about what we have.</>,
              <>My love for you isn't the kind that only shows up when things are easy. It's <span style={{color:'#d4af37',fontWeight:600}}>the kind that stays</span>. Through the bad moods, the misunderstandings, the days when we're not our best selves. I look at all of it and I still think <em>"yeah, she's worth every bit of this."</em> Because you are, V. You genuinely are.</>,
              <>So I just want you to know, from me to you, no games, no pretending: <span style={{fontStyle:'italic',color:'#ff8fa3',fontWeight:600}}>I'm really in this with you.</span> I want to be the reason you feel good on the days when everything else feels heavy. You deserve someone who shows up for you consistently and chooses you on purpose. I want to be that person for you, every single day.</>
            ].map((para, i) => (
              <p key={i} style={{
                fontFamily:"'Cormorant Garamond', serif",
                fontSize:'clamp(1rem,2.8vw,1.18rem)',
                lineHeight:1.9,
                color:'rgba(255,235,240,0.88)',
                marginBottom:22,
                textAlign:'justify',
                textShadow:'0 1px 8px rgba(0,0,0,.6)',
                opacity:0,
                animation:`fadeUp .8s ease forwards ${.5+i*.25}s`,
              }}>{para}</p>
            ))}

            {/* Divider */}
            <div style={{display:'flex',alignItems:'center',gap:14,margin:'32px 0',opacity:.4}}>
              <div style={{flex:1,height:1,background:'linear-gradient(90deg,transparent,#ff8fa3)'}}/>
              <span style={{color:'#ff8fa3',fontSize:'1.1rem'}}>♥</span>
              <div style={{flex:1,height:1,background:'linear-gradient(90deg,#ff8fa3,transparent)'}}/>
            </div>

            {/* Closing */}
            <div style={{textAlign:'right',paddingRight:8}}>
              <div style={{fontFamily:"'Dancing Script',cursive",color:'rgba(255,200,210,.6)',fontSize:'1rem',marginBottom:4}}>With all my heart, always,</div>
              <div style={{fontFamily:"'Dancing Script',cursive",color:'rgba(255,200,210,.6)',fontSize:'1rem',marginBottom:10}}>yours truly 💋</div>
              <div style={{
                fontFamily:"'Dancing Script',cursive",
                fontSize:'clamp(2rem,6vw,2.8rem)',
                color:'#ff8fa3',
                display:'inline-block',
                textShadow:'0 0 20px rgba(255,100,140,.6),0 0 40px rgba(255,100,140,.3)',
                animation:'signIn 1.5s cubic-bezier(.34,1.56,.64,1) both 2.5s',
              }}>Johwell</div>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
}
